import torch
from src.manifolds.euclidean import Euclidean
from src.manifolds.euclidean.standard import StandardEuclidean

class PullbackEuclidean(Euclidean):
    """ Base class describing a R^d under a l^2-pullback Riemannian geometry generated by a Diffeomorphism """

    def __init__(self, diffeomorphism):
        super().__init__(diffeomorphism.d)
        self.phi = diffeomorphism # Diffeomorphism
        self.manifold = StandardEuclidean(self.d)

    def barycentre(self, x):
        """

        :param x: N x d
        :return: d
        """
        return self.phi.inverse(self.manifold.barycentre(self.phi.forward(x))[None])[0]

    def inner(self, x, X, Y):
        """

        :param x: N x d
        :param X: N x M x d
        :param Y: N x L x d
        :return: N x M x L
        """
        _, M, _ = X.shape
        _, L, _ = Y.shape
        device = x.device
        return self.manifold.inner(self.phi.forward(x),
                                   self.phi.differential_forward((x[:, None] * torch.ones(M, device=device)[None, :, None]).reshape(-1, self.d), X.reshape(-1, self.d)).reshape(X.shape),
                                   self.phi.differential_forward((x[:, None] * torch.ones(L, device=device)[None, :, None]).reshape(-1, self.d), Y.reshape(-1, self.d)).reshape(Y.shape)
                                   )

    def geodesic(self, x, y, t):
        """

        :param x: d
        :param y: d
        :param t: N
        :return: N x d
        """
        return self.phi.inverse(self.manifold.geodesic(self.phi.forward(x[None])[0], self.phi.forward(y[None])[0], t))

    def log(self, x, y):
        """

        :param x: d
        :param y: N x d
        :return: N x d
        """
        N, _ = y.shape
        device = x.device
        print(self.phi.forward(x[None])[0].to(device))
        print(self.phi.forward(y).to(device))
        return self.phi.differential_inverse(self.phi.forward(x[None]).to(device) * torch.ones(N, device=device)[:, None],
                                                self.manifold.log(self.phi.forward(x[None])[0].to(device), self.phi.forward(y).to(device))
                                                )

    def exp(self, x, X):
        """

        :param x: d
        :param X: N x d
        :return: N x d
        """
        N, _ = X.shape
        device = x.device
        return self.phi.inverse(self.manifold.exp(self.phi.forward(x[None])[0].to(device), self.phi.differential_forward(x[None].to(device) * torch.ones(N, device=device)[:, None], X.to(device))))

    def distance(self, x, y):
        """

        :param x: N x M x d
        :param y: N x L x d
        :return: N x M x L
        """
        return self.manifold.distance(self.phi.forward(x.reshape(-1, self.d)).reshape(x.shape), self.phi.forward(y.reshape(-1, self.d)).reshape(y.shape))

    def parallel_transport(self, x, X, y):
        """

        :param x: d
        :param X: N x d
        :param y: d
        :return: N x d
        """
        N, _ = X.shape
        device = x.device
        return self.phi.differential_inverse(self.phi.forward(y[None]).to(device) * torch.ones(N, device=device)[:, None],
                                                self.manifold.parallel_transport(self.phi.forward(x[None])[0].to(device),
                                                                                 self.phi.differential_forward(x[None].to(device) * torch.ones(N, device=device)[:, None], X.to(device)),
                                                                                 self.phi.forward(y[None])[0].to(device)
                                                                                 )
                                                )